#!/bin/bash
# generated by le chat mistral
# Directory containing the .rt files
SCENE_DIR="test_scenes"
# Loop through all .rt files in the directory
for rt_file in "$SCENE_DIR"/*.rt; do
    echo "Running miniRT with $rt_file"
    echo "Press ESC in the miniRT window to exit and continue to the next file..."

    # Run miniRT and wait for it to exit
    ./miniRT "$rt_file"

    echo "Closed $rt_file"
done

echo "All scenes processed."
